#ifndef SNITCH_CONFIG_HPP
#define SNITCH_CONFIG_HPP
// PROTOTYPE (issue #18): hand-filled copy of snitch's include/snitch/snitch_config.hpp.config
// (normally generated by CMake/Meson) for a freestanding, small-MCU build.
// Lowered limits are marked "lowered"; the upstream defaults are in brackets.

#include <version>

#define SNITCH_VERSION "1.3.2"
#define SNITCH_FULL_VERSION "1.3.2.c29ce5b"
#define SNITCH_VERSION_MAJOR 1
#define SNITCH_VERSION_MINOR 3
#define SNITCH_VERSION_PATCH 2

// clang-format off
#ifndef SNITCH_MAX_TEST_CASES
#define SNITCH_MAX_TEST_CASES             64  // lowered [5000]; build.sh also measures 16
#endif
#define SNITCH_MAX_NESTED_SECTIONS        2   // lowered [8]
#define SNITCH_MAX_EXPR_LENGTH            96  // lowered [1024]
#define SNITCH_MAX_MESSAGE_LENGTH         96  // lowered [1024]
#define SNITCH_MAX_TEST_NAME_LENGTH       64  // lowered [1024]
#define SNITCH_MAX_TAG_LENGTH             16  // lowered [256]
#define SNITCH_MAX_CAPTURES               2   // lowered [8]
#define SNITCH_MAX_CAPTURE_LENGTH         32  // lowered [256]
#define SNITCH_MAX_UNIQUE_TAGS            4   // lowered [1024]
#define SNITCH_MAX_COMMAND_LINE_ARGS      32  // lowered [1024]; also sizes the CLI option table, so >= 32
#define SNITCH_MAX_REGISTERED_REPORTERS   1   // lowered [8]
#define SNITCH_MAX_PATH_LENGTH            1   // lowered [1024]
#define SNITCH_MAX_REPORTER_SIZE_BYTES    128 // [128]
#define SNITCH_MAX_FILE_OBJECT_SIZE_BYTES 4   // lowered [128]

#define SNITCH_DEFINE_MAIN                     0 // we call run_tests() ourselves
#define SNITCH_WITH_STDOUT                     0 // freestanding: output via console_print
#define SNITCH_WITH_STD_FILE_IO                0
#define SNITCH_WITH_EXCEPTIONS                 0
#define SNITCH_WITH_TIMINGS                    0 // no clock on bare metal
#define SNITCH_WITH_SHORTHAND_MACROS           1
#define SNITCH_DEFAULT_WITH_COLOR              0
#define SNITCH_CONSTEXPR_FLOAT_USE_BITCAST     1
#ifndef SNITCH_APPEND_TO_CHARS
#define SNITCH_APPEND_TO_CHARS                 1 // build.sh can override, to measure both
#endif
#define SNITCH_DECOMPOSE_SUCCESSFUL_ASSERTIONS 0
#define SNITCH_WITH_ALL_REPORTERS              0
#define SNITCH_WITH_TEAMCITY_REPORTER          0
#define SNITCH_WITH_CATCH2_XML_REPORTER        0
#define SNITCH_WITH_MULTITHREADING             0
#define SNITCH_SHARED_LIBRARY                  0
#define SNITCH_ENABLE                          1
// clang-format on

// ---- Below: unchanged from upstream ----

#if defined(_MSC_VER)
#    if defined(_KERNEL_MODE) || (defined(_HAS_EXCEPTIONS) && !_HAS_EXCEPTIONS)
#        define SNITCH_EXCEPTIONS_NOT_AVAILABLE
#    endif
#elif defined(__clang__) || defined(__GNUC__)
#    if !defined(__EXCEPTIONS)
#        define SNITCH_EXCEPTIONS_NOT_AVAILABLE
#    endif
#endif

#if defined(SNITCH_EXCEPTIONS_NOT_AVAILABLE)
#    undef SNITCH_WITH_EXCEPTIONS
#    define SNITCH_WITH_EXCEPTIONS 0
#endif

#if SNITCH_WITH_MULTITHREADING
#    define SNITCH_THREAD_LOCAL thread_local
#else
#    define SNITCH_THREAD_LOCAL
#endif

#if !defined(__cpp_lib_bit_cast)
#    undef SNITCH_CONSTEXPR_FLOAT_USE_BITCAST
#    define SNITCH_CONSTEXPR_FLOAT_USE_BITCAST 0
#endif

#if (!defined(__cpp_lib_to_chars)) || (defined(_GLIBCXX_RELEASE) && _GLIBCXX_RELEASE <= 11) ||     \
    (defined(_LIBCPP_VERSION) && _LIBCPP_VERSION <= 14000) ||                                      \
    (defined(_MSC_VER) && _MSC_VER <= 1924)
#    undef SNITCH_APPEND_TO_CHARS
#    define SNITCH_APPEND_TO_CHARS 0
#endif

#define SNITCH_EXPORT

#endif
